-ratio:3/2;object-fit:cover}.tl-fabric h2{margin:15px 0}.tl-fabric-empty{grid-template-columns:1fr}.tl-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;padding-block:35px;border-top:1px solid var(--border-color)}.tl-service h3{font-family:var(--font-body);font-size:.9rem;letter-spacing:0}.tl-service p{font-size:.8rem}.tl-services:empty{display:none}\n.tl-theme .lb-product-detail{width:min(1280px,calc(100% - 112px));margin:auto;padding-block:32px 60px}.tl-theme .lb-product-detail__layout{display:grid;grid-template-columns:1.2fr 1fr;gap:65px}.tl-theme .lb-product-detail__gallery-image{aspect-ratio:4/5;object-fit:cover;width:100%}.tl-theme .lb-product-detail__title{font-size:clamp(1.8rem,3vw,2.8rem);font-weight:400}.tl-theme .lb-product-detail__price-current{font-size:1.25rem}.tl-theme .lb-product-detail__cta{border-radius:4px;min-height:48px}.tl-theme .lb-product-detail__cta--primary{background:var(--primary);color:var(--tl-action-label,#fff)}.tl-theme .lb-product-detail__variant-values{gap:9px}.tl-theme .lb-product-detail__variant-values button{min-width:44px;min-height:44px;border:1px solid var(--tl-border);border-radius:0;background:var(--background)}.tl-theme .lb-product-detail__variant-values button[aria-pressed=\"true\"]{background:var(--primary);color:var(--tl-action-label,#fff)}.tl-theme .lb-product-detail__variant-values button[disabled]{text-decoration:line-through}.tl-theme .lb-product-detail__info{min-width:0}.tl-fit{border-top:1px solid var(--border-color);padding-top:35px;margin-top:35px}.tl-fit h2{font-size:1.6rem}.tl-fit p{font-size:.9rem}.tl-fit table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:.8rem;margin:20px 0}.tl-fit caption{text-align:left;margin-bottom:12px}.tl-fit th,.tl-fit td{text-align:left;border-bottom:1px solid var(--border-color);padding:12px 8px;overflow-wrap:anywhere}.tl-fit thead{background:var(--tl-stone)}.tl-fit summary{min-height:44px;cursor:pointer;font-family:var(--font-display);f