n linklists.main_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}\n      {% else %}<a href=\"{{ routes.all_products_collection_url }}\">Products</a><a href=\"{{ routes.search_url }}\">Search</a><a href=\"{{ routes.cart_url }}\">Cart</a><a href=\"{{ routes.account_url }}\">Account</a>{% endif %}\n    </nav>\n  </header>\n  <main id=\"MainContent\">\n    {{ content_for_layout | raw }}\n  </main>\n  <footer class=\"lb-layout__footer\">\n    {% if linklists.footer.links.size > 0 %}<nav class=\"lb-layout__nav\" aria-label=\"Footer\">{% for link in linklists.footer.links %}<a href=\"{{ link.url | store_url }}\">{{ link.title }}</a>{% endfor %}</nav>{% endif %}\n    <p class=\"lb-layout__legal\">&copy; {{ shop.name }}</p>\n  </footer>\n  {{ content_for_footer | raw }}\n</body>\n</html>"}},"manifest_version":"2026-06-liquid-sections","schema_manifest":{"blocks_path":"blocks/*.liquid","bundle_schema_version":"2026-06-liquid-sections","engine":"liquid","layout_path":"layout/theme.liquid","locales_path":"locales/*.json","sections_path":"sections/*.liquid","settings_data_path":"config/settings_data.json","settings_path":"config/settings_schema.json","templates_path":"templates/*.json"},"section_schemas":{"404-page":{"blocks_schema":{},"defaults":{},"description":"Liquid section file sections/404-page.liquid","name":"404 Not Found","presets":[{"name":"404 Not Found","settings":{}}],"renderer_key":"liquid.section.404-page","settings_schema":{},"source_path":"sections/404-page.liquid","type":"404-page"},"about-section":{"blocks_schema":{},"defaults":{},"description":"Liquid section file sections/about-section.liquid","name":"Fabric and care editorial","presets":[{"name":"Fabric and care editorial","settings":{}}],"renderer_key":"liquid.section.about-section","settings_schema":{"content":{"default":"","label":"Merchant editorial text","type":"text"},"image":{"label":"Editorial photograph","type