{ section.settings.heading }}</h2>\n    {% if section.settings.subheading != blank %}<p class=\"lb-video-hero__subheading\">{{ section.settings.subheading }}</p>{% endif %}\n  </div>\n  {% if section.settings.videoUrl != blank %}<div class=\"lb-video-hero__embed\"><iframe src=\"{{ section.settings.videoUrl | video_url }}\" title=\"{{ section.settings.heading }}\" loading=\"lazy\" sandbox=\"allow-scripts allow-same-origin allow-presentation\" allowfullscreen></iframe></div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Video Hero\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"See the fit in motion\",\"id\":\"heading\"},{\"type\":\"textarea\",\"label\":\"Subheading\",\"default\":\"A quick look at how each drop moves, from the box to your feet.\",\"id\":\"subheading\"},{\"type\":\"url\",\"label\":\"Video embed URL\",\"info\":\"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.\",\"id\":\"videoUrl\"}],\"blocks\":[],\"presets\":[{\"name\":\"Video Hero\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"}},"templates":{"article":{"layout":"theme","name":"Article","order":["article-content-default"],"sections":{"article-content-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"article-content"}}},"blog":{"layout":"theme","name":"Blog","order":["blog-listing-default"],"sections":{"blog-listing-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"heading":"Our Blog"},"type":"blog-listing"}}},"cart":{"layout":"theme","name":"LetBuyy Core cart","order":["cart-summary-default"],"sections":{"cart-summary-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"cart-summary"}}},"collection":{"layout":"theme","name":"LetBuyy Core collection","order":["sense-collectionFilter-collection","sense-productGrid-collection"],"sections"