 SELECT * INTO STRICT t FROM public.themes WHERE id=(item->>'id')::uuid AND slug=item->>'slug' AND owned_by_site_id IS NULL AND NOT is_site_private FOR UPDATE;
 IF t.is_active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Sense211 inactive catalog conflict'; END IF;
 IF (SELECT count(*) FROM public.theme_packages WHERE slug=t.slug OR legacy_theme_id=t.id)<>1 THEN RAISE EXCEPTION 'Sense211 package identity conflict'; END IF;
 SELECT * INTO STRICT p FROM public.theme_packages WHERE (slug=t.slug OR legacy_theme_id=t.id) AND deleted_at IS NULL AND status='active' FOR UPDATE;
 IF p.slug<>t.slug OR p.legacy_theme_id IS DISTINCT FROM t.id THEN RAISE EXCEPTION 'Sense211 canonical package identity conflict'; END IF;
 IF t.version IS DISTINCT FROM '2.1.0' AND t.version IS DISTINCT FROM '2.1.1' THEN RAISE EXCEPTION 'Sense211 stale prior catalog version'; END IF;
 
 body:=item#>'{previousPersistence,themePackageVersion}';
 SELECT * INTO STRICT old_version FROM public.theme_package_versions WHERE theme_package_id=p.id AND version=body->>'version' FOR UPDATE;
 IF old_version.deleted_at IS NOT NULL OR (to_jsonb(old_version)-ARRAY['id','theme_package_id','published_at','created_by','created_at','updated_at','deleted_at']) IS DISTINCT FROM (body||jsonb_build_object('checksum',body->'checksum')) THEN RAISE EXCEPTION 'Immutable sense211 previousPersistence version conflict'; END IF;
 body:=item#>'{previousPersistence,schemaManifest}';
 SELECT * INTO STRICT s FROM public.theme_schema_manifests WHERE theme_package_version_id=old_version.id FOR UPDATE;
 IF (to_jsonb(s)-ARRAY['id','theme_package_version_id','created_at','updated_at']) IS DISTINCT FROM body THEN RAISE EXCEPTION 'Immutable sense211 previousPersistence schema conflict'; END IF;
 body:=item#>'{previousPersistence,rendererManifest}';
 SELECT * INTO STRICT r FROM public.theme_renderer_manifests WHERE theme_package_version_id=old_version.id FOR UPDATE;
 IF (to_jsonb(r)-ARRAY['id','theme_package_version_id','created_at','updated_at']) IS DISTINCT FROM body THEN RAISE EXCEPTION 'Immutable sense211 previousPersistence renderer conflict'; END IF;
 IF t.version='2.1.0' THEN
  IF ((
 t.version='2.1.0' AND t.name IS NOT DISTINCT FROM item->>'name' AND t.category IS NOT DISTINCT FROM item->>'category'
 AND t.default_template IS NOT DISTINCT FROM item->'previousDocument'
 AND t.section_schemas IS NOT DISTINCT FROM item#>'{previousPersistence,schemaManifest,section_schemas}'
 AND t.block_schemas IS NOT DISTINCT FROM item#>'{previousPersistence,schemaManifest,block_schemas}'
 AND t.settings_schema IS NOT DISTINCT FROM item#>'{previousPersistence,schemaManifest,settings_schema}'
 AND t.renderer_manifest IS NOT DISTINCT FROM item#>'{previousDocument,liquidBundle,renderer}'
 AND t.schema_version IS NOT DISTINCT FROM item#>>'{previousPersistence,themePackageVersion,schema_version}'
 AND t.renderer_version IS NOT DISTINCT FROM item#>>'{previousPersistence,themePackageVersion,renderer_version}')) IS NOT TRUE OR t.config ? 'firstPartySense211' OR t.config#>>'{firstPartyCustomization210,payloadSha256}' IS DISTINCT FROM 'cf10d8f413585425416d7555a2c786fe6b41d9e43b7add32f02043cf69d466bb' THEN RAISE EXCEPTION 'Sense211 prior catalog differs from exact captured210'; END IF;
 END IF;
 body:=item#>'{persistence,themePackageVersion}';
 INSERT INTO public.theme_package_versions(theme_package_id,version,version_number,release_status,renderer_version,schema_version,compatibility_range,package_manifest,checksum,published_at)
 SELECT p.id,x.version,x.version_number,x.release_status,x.renderer_version,x.schema_version,x.compatibility_range,x.package_manifest,x.checksum,now()
 FROM jsonb_populate_record(NULL::public.theme_package_versions,body) x ON CONFLICT(theme_package_id,version) DO NOTHING;
 SELECT * INTO STRICT v FROM public.theme_package_versions WHERE theme_package_id=p.id AND version='2.1.1' FOR UPDATE;
 body:=item#>'{persistence,schemaManifest}';
 INSERT INTO public.theme_schema_manifests(theme_package_version_id,manifest_version,schema_manifest,section_schemas,block_schemas,settings_schema,template_schema,layout_schema,validation_rules)
 SELECT v.id,x.manifest_version,x.schema_manifest,x.section_schemas,x.block_schemas,x.settings_schema,x.template_schema,x.layout_schema,x.validation_rules FROM jsonb_populate_record(NULL::public.theme_schema_manifests,body) x ON CONFLICT(theme_package_version_id) DO NOTHING;
 body:=item#>'{persistence,rendererManifest}';
 INSERT INTO public.theme_renderer_manifests(theme_package_version_id,renderer_manifest,approved_renderer_keys,asset_manifest,performance_budget)
 SELECT v.id,x.renderer_manifest,x.approved_renderer_keys,x.asset_manifest,x.performance_budget FROM jsonb_populate_record(NULL::public.theme_renderer_manifests,body) x ON CONFLICT(theme_package_version_id) DO NOTHING;
 
 body:=item#>'{persistence,themePackageVersion}';
 SELECT * INTO STRICT v FROM public.theme_package_versions WHERE theme_package_id=p.id AND version=body->>'version' FOR UPDATE;
 IF v.deleted_at IS NOT NULL OR (to_jsonb(v)-ARRAY['id','theme_package_id','published_at','created_by','created_at','updated_at','deleted_at']) IS DISTINCT FROM (body||jsonb_build_object('checksum',body->'checksum')) THEN RAISE EXCEPTION 'Immutable sense211 persistence version conflict'; END IF;
 body:=item#>'{persistence,schemaManifest}';
 SELECT * INTO STRICT s FROM public.theme_schema_manifests WHERE theme_package_version_id=v.id FOR UPDATE;
 IF (to_jsonb(s)-ARRAY['id','theme_package_version_id','created_at','updated_at']) IS DISTINCT FROM body THEN RAISE EXCEPTION 'Immutable sense211 persistence schema conflict'; END IF;
 body:=item#>'{persistence,rendererManifest}';
 SELECT * INTO STRICT r FROM public.theme_renderer_manifests WHERE theme_package_version_id=v.id FOR UPDATE;
 IF (to_jsonb(r)-ARRAY['id','theme_package_version_id','created_at','updated_at']) IS DISTINCT FROM body THEN RAISE EXCEPTION 'Immutable sense211 persistence renderer conflict'; END IF;
 IF t.version='2.1.1' THEN
  IF ((
 t.version='2.1.1' AND t.name IS NOT DISTINCT FROM item->>'name' AND t.category IS NOT DISTINCT FROM item->>'category'
 AND t.default_template IS NOT DISTINCT FROM item->'document'
 AND t.section_schemas IS NOT DISTINCT FROM item#>'{persistence,schemaManifest,section_schemas}'
 AND t.block_schemas IS NOT DISTINCT FROM item#>'{persistence,schemaManifest,block_schemas}'
 AND t.settings_schema IS NOT DISTINCT FROM item#>'{persistence,schemaManifest,settings_schema}'
 AND t.renderer_manifest IS NOT DISTINCT FROM item#>'{document,liquidBundle,renderer}'
 AND t.schema_version IS NOT DISTINCT FROM item#>>'{persistence,themePackageVersion,schema_version}'
 AND t.renderer_version IS NOT DISTINCT FROM item#>>'{persistence,themePackageVersion,renderer_version}')) IS NOT TRUE THEN RAISE EXCEPTION 'Sense211 catalog replay conflict'; END IF;
  
 prior:=t.config#>'{firstPartySense211,previous}';
 IF jsonb_typeof(t.config) IS DISTINCT FROM 'object' OR jsonb_typeof(t.config->'firstPartySense211') IS DISTINCT FROM 'object'
 OR jsonb_typeof(prior) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Sense211 checkpoint or replay conflict'; END IF;
 IF ARRAY(SELECT key FROM jsonb_object_keys(prior) AS k(key) ORDER BY key) IS DISTINCT FROM ARRAY['block_schemas','category','config','default_template','name','renderer_manifest','renderer_version','schema_version','section_schemas','settings_schema','version']::text[]
 OR ARRAY(SELECT key FROM jsonb_object_keys(t.config->'firstPartySense211') AS k(key) ORDER BY key) IS DISTINCT FROM ARRAY['payloadSha256','previous']::text[]
 OR t.config#>>'{firstPartySense211,payloadSha256}' IS DISTINCT FROM '644acaf43df7aa48c251260218d9738c73ef7e595034545b981bbf57098bbb56'
 OR prior->'name' IS DISTINCT FROM item#>'{name}'
 OR prior->'category' IS DISTINCT FROM item#>'{category}'
 OR prior->'version' IS DISTINCT FROM item#>'{previousVersion}'
 OR prior->'default_template' IS DISTINCT FROM item#>'{previousDocument}'
 OR prior->'section_schemas' IS DISTINCT FROM item#>'{previousPersistence,schemaManifest,section_schemas}'
 OR prior->'block_schemas' IS DISTINCT FROM item#>'{previousPersistence,schemaManifest,block_schemas}'
 OR prior->'settings_schema' IS DISTINCT FROM item#>'{previousPersistence,schemaManifest,settings_schema}'
 OR prior->'renderer_manifest' IS DISTINCT FROM item#>'{previousDocument,liquidBundle,renderer}'
 OR prior->'schema_version' IS DISTINCT FROM item#>'{previousPersistence,themePackageVersion,schema_version}'
 OR prior->'renderer_version' IS DISTINCT FROM item#>'{previousPersistence,themePackageVersion,renderer_version}'
 OR jsonb_typeof(prior->'config') IS DISTINCT FROM 'object' OR (prior->'config') ? 'firstPartySense211'
 OR prior#>>'{config,firstPartyCustomization210,payloadSha256}' IS DISTINCT FROM 'cf10d8f413585425416d7555a2c786fe6b41d9e43b7add32f02043cf69d466bb'
 OR (t.config-'firstPartySense211') IS DISTINCT FROM prior->'config'
 THEN RAISE EXCEPTION 'Sense211 checkpoint or replay conflict'; END IF;
  CONTINUE;
 END IF;
 prior:=jsonb_build_object('name',t.name,'category',t.category,'version',t.version,'default_template',t.default_template,'section_schemas',t.section_schemas,'block_schemas',t.block_schemas,'settings_schema',t.settings_schema,'renderer_manifest',t.renderer_manifest,'schema_version',t.schema_version,'renderer_version',t.renderer_version,'config',t.config);
 UPDATE public.themes SET name=item->>'name',category=item->>'category',version='2.1.1',default_template=item->'document',
 section_schemas=item#>'{persistence,schemaManifest,section_schemas}',block_schemas=item#>'{persistence,schemaManifest,block_schemas}',settings_schema=item#>'{persistence,schemaManifest,settings_schema}',renderer_manifest=item#>'{document,liquidBundle,renderer}',schema_version=v.schema_version,renderer_version=v.renderer_version,
 config=t.config||jsonb_build_object('firstPartySense211',jsonb_build_object('payloadSha256','644acaf43df7aa48c251260218d9738c73ef7e595034545b981bbf57098bbb56','previous',prior)),updated_at=now() WHERE id=t.id;
 END LOOP;
END;
